input.new_string:
const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const ADMIN_FEE = 5;

const quote = (): QuoteResult => {
  const surcharged = SWORD_BASE_PREMIUM * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
  return { premium: surcharged + ADMIN_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return { results: scenario.steps.map(quote) };
};

